// @vitest-environment node
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
// @ts-expect-error — a plain .mjs script with no types; it exports bundleMcp and OUT
import { bundleMcp, OUT } from "../scripts/build-mcp.mjs";

/**
 * `tools/quadra-mcp/skills.mjs` is GENERATED from `src/skills/mcp.ts`. A generated file that
 * nobody regenerates is the same drift as a hand-kept copy — the agent would run yesterday's
 * skills. This rebuilds it in memory and compares, byte for byte.
 */
describe("the MCP skill bundle", () => {
  it("is exactly what `npm run build:mcp` builds from today's source", async () => {
    const fresh = (await bundleMcp()) as string;
    expect(readFileSync(OUT as string, "utf8") === fresh, "tools/quadra-mcp/skills.mjs is stale — run `npm run build:mcp`").toBe(true);
    expect(fresh.startsWith("// GENERATED by scripts/build-mcp.mjs")).toBe(true);
  });
});
